import{_ as d,C as g,o as i,c as h,a0 as o,b as s,w as t,a,E as l,a1 as c,j as n}from"./chunks/framework.DYS8d9tm.js";const S=JSON.parse('{"title":"📥 Precision Data Ingestion Flow","description":"","frontmatter":{},"headers":[],"relativePath":"technical/architecture/ingestion.md","filePath":"technical/architecture/ingestion.md"}'),u={name:"technical/architecture/ingestion.md"};function p(m,e,f,A,b,y){const r=g("Mermaid");return i(),h("div",null,[e[3]||(e[3]=o('<h1 id="📥-precision-data-ingestion-flow" tabindex="-1">📥 Precision Data Ingestion Flow <a class="header-anchor" href="#📥-precision-data-ingestion-flow" aria-label="Permalink to &quot;📥 Precision Data Ingestion Flow&quot;">​</a></h1><p>WealthFam features a sophisticated, multi-channel ingestion pipeline designed to minimize manual entry while maintaining 100% data accuracy through idempotent hashing and tiered parsing logic.</p><hr><h2 id="⚡-multi-channel-ingestion" tabindex="-1">⚡ Multi-Channel Ingestion <a class="header-anchor" href="#⚡-multi-channel-ingestion" aria-label="Permalink to &quot;⚡ Multi-Channel Ingestion&quot;">​</a></h2><p>Our system captures data from three primary streams:</p><ol><li><strong>Mobile SMS Ingestion</strong>: Real-time capture of bank transaction alerts directly from Android background listeners.</li><li><strong>Email IMAP Sync</strong>: Periodic scanning of authorized email accounts for bank statements and CAMS PDFs. <ul><li><strong>Automated Statement Capture</strong>: Automatically identifies, downloads, and pre-processes bank statement PDFs (e.g., HDFC, Swiggy HDFC) from incoming emails.</li></ul></li><li><strong>Manual Web Ingestion</strong>: High-fidelity bulk uploads via CSV, Excel, or PDF files through the desktop dashboard.</li></ol><hr><h2 id="🏗️-the-pipeline-lifecycle" tabindex="-1">🏗️ The Pipeline Lifecycle <a class="header-anchor" href="#🏗️-the-pipeline-lifecycle" aria-label="Permalink to &quot;🏗️ The Pipeline Lifecycle&quot;">​</a></h2>',8)),(i(),s(c,null,{default:t(()=>[l(r,{id:"mermaid-41",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20Raw%20as%20Raw%20Source%20(SMS%2FEmail%2FWeb)%0A%20%20%20%20participant%20Dedup%20as%20Deduplication%20(MD5)%0A%20%20%20%20participant%20Filter%20as%20Logic%20Filter%0A%20%20%20%20participant%20Engine%20as%20Tiered%20Parser%20Engine%0A%20%20%20%20participant%20LLM%20as%20Gemini%20AI%20Fallback%0A%20%20%20%20participant%20Ledger%20as%20Confirmed%20Ledger%0A%0A%20%20%20%20Raw-%3E%3EDedup%3A%20Input%20Raw%20String%2FFile%0A%20%20%20%20Dedup-%3E%3EDedup%3A%20Generate%20Unique%20ID%20(MD5)%0A%20%20%20%20Dedup--%3E%3ERaw%3A%20Reject%20if%20ID%20exists%20(Idempotency)%0A%20%20%20%20%0A%20%20%20%20Dedup-%3E%3EFilter%3A%20Pass%20Unique%20Payload%0A%20%20%20%20Filter-%3E%3EFilter%3A%20Apply%20Ignore%20Patterns%20(e.g.%2C%20OTPs%2C%20Spam)%0A%20%20%20%20%0A%20%20%20%20Filter-%3E%3EEngine%3A%20Structured%20Data%20Stream%0A%20%20%20%20%0A%20%20%20%20alt%20Static%20Match%0A%20%20%20%20%20%20%20%20Engine-%3E%3EEngine%3A%20Match%20Static%20Regex%2FTemplate%0A%20%20%20%20else%20Pattern%20Guessing%0A%20%20%20%20%20%20%20%20Engine-%3E%3EEngine%3A%20Heuristic%20Inference%0A%20%20%20%20else%20AI%20Parsing%0A%20%20%20%20%20%20%20%20Engine-%3E%3ELLM%3A%20Request%20Unstructured%20Extraction%0A%20%20%20%20%20%20%20%20LLM--%3E%3EEngine%3A%20Structured%20JSON%20Response%0A%20%20%20%20end%0A%0A%20%20%20%20Engine-%3E%3ELedger%3A%20Commit%20Synchronized%20Transaction%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=n("h3",{id:"🏦-cams-kfintech-investment-ledger",tabindex:"-1"},[a("🏦 CAMS/KFintech & Investment Ledger "),n("a",{class:"header-anchor",href:"#🏦-cams-kfintech-investment-ledger","aria-label":'Permalink to "🏦 CAMS/KFintech & Investment Ledger"'},"​")],-1)),e[5]||(e[5]=n("p",null,[a("Our investment sync handles the complex extraction from bank-issued PDFs and enforces an "),n("strong",null,"Ironclad Precision Standard"),a(" for the life of the asset.")],-1)),(i(),s(c,null,{default:t(()=>[l(r,{id:"mermaid-48",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20Email%5BIMAP%20Sync%20Engine%5D%20--%3E%7CFind%20Attachments%7C%20PDF%5BCAMS%2FKFintech%20PDF%5D%0A%20%20%20%20PDF%20--%3E%7CSecure%20Password%7C%20Extraction%5BPrecision%20Extraction%20Microservice%5D%0A%20%20%20%20Extraction%20--%3E%7CMask%20PII%7C%20Anonymized%5BAnonymized%20JSON%5D%0A%20%20%20%20Anonymized%20--%3E%7CMapping%7C%20Positions%5BInvestment%20Positions%5D%0A%20%20%20%20Positions%20--%3E%7CDecimal%20Rebuild%7C%20Hardened%5BHardened%20Investment%20Ledger%5D%0A%20%20%20%20Hardened%20--%3E%7CXIRR%20Engine%7C%20UI%5BDashboard%20Portfolio%20View%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=o('<p>For a deep-dive into the CAMS/KFintech extraction logic, see the <strong><a href="./../data ingestion/cas_ingestion.html">CAS Ingestion Technical Specification</a></strong>.</p><h4 id="the-hardened-ledger-principles" tabindex="-1"><strong>The Hardened Ledger Principles</strong> <a class="header-anchor" href="#the-hardened-ledger-principles" aria-label="Permalink to &quot;**The Hardened Ledger Principles**&quot;">​</a></h4><ol><li><strong>Identity Preservation</strong>: Unlike traditional systems that delete and recreate holdings during a sync, WealthFam performs <strong>In-Place Updates</strong>. This preserves the internal UUID of your holdings, ensuring that your linked <strong>Investment Goals</strong>, historical charts, and frontend caches never break (Zero 404 Resilience).</li><li><strong>Absolute Decimal Precision</strong>: Every NAV, unit count, and cost-basis calculation is performed via Python&#39;s <code>Decimal</code> library. This eliminates the &quot;Floating Point Drift&quot; common in financial apps, where rounding errors accumulate over hundreds of SIP transactions.</li><li><strong>Non-Destructive Management (Soft-Delete)</strong>: Manual cleanup of &quot;junk&quot; data or correction of duplicate CAMS entries is non-destructive. Transactions are marked with <code>is_deleted</code>, allowing for a full audit trail and the ability to &quot;un-delete&quot; historical data.</li></ol><h4 id="the-what-if-impact-analysis" tabindex="-1"><strong>The &#39;What-If&#39; Impact Analysis</strong> <a class="header-anchor" href="#the-what-if-impact-analysis" aria-label="Permalink to &quot;**The &#39;What-If&#39; Impact Analysis**&quot;">​</a></h4><p>When a user attempts to surgically delete a transaction or a folio, the system invokes the <strong>Predictive Projection Engine</strong>:</p><ul><li><strong>Step 1</strong>: It creates a transient, in-memory clone of the holding&#39;s order history.</li><li><strong>Step 2</strong>: It applies the proposed deletion to the clone.</li><li><strong>Step 3</strong>: It re-executes the IRR and Average Cost algorithms on the transient data.</li><li><strong>Step 4</strong>: It broadcasts the delta (e.g., &quot;Profit will drop by ₹540, XIRR will rise to 14.2%&quot;) to the UI <em>before</em> the user commits the change.</li></ul><h3 id="📱-real-time-sms-triage" tabindex="-1">📱 Real-Time SMS Triage <a class="header-anchor" href="#📱-real-time-sms-triage" aria-label="Permalink to &quot;📱 Real-Time SMS Triage&quot;">​</a></h3><p>How we handle incoming bank alerts with varying degrees of certainty.</p>',8)),(i(),s(c,null,{default:t(()=>[l(r,{id:"mermaid-106",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20App%20as%20Android%20Listener%0A%20%20%20%20participant%20Parser%20as%20Ingestion%20MS%0A%20%20%20%20participant%20Queue%20as%20Triage%20Queue%0A%20%20%20%20participant%20Ledger%20as%20Ledger%20DB%0A%0A%20%20%20%20App-%3E%3EParser%3A%20Encrypted%20SMS%20%2B%20GPS%0A%20%20%20%20Parser-%3E%3EParser%3A%20Confidence%20Check%0A%20%20%20%20alt%20High%20Confidence%20(%3E95%25)%0A%20%20%20%20%20%20%20%20Parser-%3E%3ELedger%3A%20Auto-Commit%20Transaction%0A%20%20%20%20%20%20%20%20Ledger--%3E%3EApp%3A%20WebSocket%20Push%20(Confirmed)%0A%20%20%20%20else%20Low%20Confidence%0A%20%20%20%20%20%20%20%20Parser-%3E%3EQueue%3A%20Flag%20for%20Review%0A%20%20%20%20%20%20%20%20Queue--%3E%3EApp%3A%20Notification%20(Needs%20Review)%0A%20%20%20%20end%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[a(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=o('<hr><h2 id="🛡️-key-technical-features" tabindex="-1">🛡️ Key Technical Features <a class="header-anchor" href="#🛡️-key-technical-features" aria-label="Permalink to &quot;🛡️ Key Technical Features&quot;">​</a></h2><h3 id="_1-idempotency-md5-hashing" tabindex="-1">1. Idempotency (MD5 Hashing) <a class="header-anchor" href="#_1-idempotency-md5-hashing" aria-label="Permalink to &quot;1. Idempotency (MD5 Hashing)&quot;">​</a></h3><p>Every ingestion attempt generates a unique hash based on the raw payload, timestamp, and source metadata. This ensures that the same SMS or email is never processed twice, even if the sync service restarts.</p><h3 id="_2-tiered-parsing-logic" tabindex="-1">2. Tiered Parsing Logic <a class="header-anchor" href="#_2-tiered-parsing-logic" aria-label="Permalink to &quot;2. Tiered Parsing Logic&quot;">​</a></h3><p>To maximize speed and minimize costs, we use a tiered approach:</p><ul><li><strong>Tier 1 (Static)</strong>: Hardcoded templates for major banks (HDFC, ICICI, etc.).</li><li><strong>Tier 2 (Heuristics)</strong>: Algorithmic identification of currency, amounts, and vendors.</li><li><strong>Tier 3 (AI Fallback)</strong>: Real-time inference using Gemini Pro for highly complex or non-standard messages.</li></ul><h3 id="_3-precision-deduplication" tabindex="-1">3. Precision Deduplication <a class="header-anchor" href="#_3-precision-deduplication" aria-label="Permalink to &quot;3. Precision Deduplication&quot;">​</a></h3><p>Beyond simple IDs, WealthFam uses &quot;Fuzzy Time-Windowing&quot; to identify duplicate transactions across different sources (e.g., an SMS alert and a bank statement entry for the same coffee purchase).</p><h3 id="_4-bank-statement-ingestion-automation" tabindex="-1">4. Bank Statement Ingestion &amp; Automation <a class="header-anchor" href="#_4-bank-statement-ingestion-automation" aria-label="Permalink to &quot;4. Bank Statement Ingestion &amp; Automation&quot;">​</a></h3><p>WealthFam supports bulk ingestion of bank statements (PDF/CSV) with automated classification rule generation.</p><p>For a detailed architectural breakdown of the PDF parsing algorithm, see the <strong><a href="./../data ingestion/statement_ingestion.html">Statement Ingestion Deep Dive</a></strong>.</p><ul><li><strong>Deep Table Parsing</strong>: Specialized parsers (e.g., <code>swiggy_hdfc.py</code>) extract data from complex bank PDF layouts.</li><li><strong>Automated Rule Generation</strong>: During ingestion, users can opt to save a classification rule based on the transaction&#39;s description.</li><li><strong>Session Isolation (Persistence Hardening)</strong>: To prevent data corruption during bulk operations, rules are &quot;expunged&quot; from the active database session after creation. This ensures that the Python-level object state (e.g., list of keywords) does not conflict with the database&#39;s storage format (e.g., JSON strings) during secondary commits.</li></ul><h2 id="🛠️-deep-how-to-troubleshooting-ingestion" tabindex="-1">🛠️ Deep How-To: Troubleshooting Ingestion <a class="header-anchor" href="#🛠️-deep-how-to-troubleshooting-ingestion" aria-label="Permalink to &quot;🛠️ Deep How-To: Troubleshooting Ingestion&quot;">​</a></h2><p>If a transaction from an SMS or Email fails to appear in your ledger, follow this Precision workflow:</p><h3 id="step-1-verify-the-audit-trail" tabindex="-1">Step 1: Verify the Audit Trail <a class="header-anchor" href="#step-1-verify-the-audit-trail" aria-label="Permalink to &quot;Step 1: Verify the Audit Trail&quot;">​</a></h3><ol><li>Navigate to <strong>Common Settings → Devices → Event Log</strong>.</li><li>Filter for event <code>sms_received</code> or <code>email_sync_started</code>.</li><li>If the event is missing, the source (Mobile/IMAP) is not communicating with the backend.</li></ol><h3 id="step-2-check-for-idempotency-rejection" tabindex="-1">Step 2: Check for Idempotency Rejection <a class="header-anchor" href="#step-2-check-for-idempotency-rejection" aria-label="Permalink to &quot;Step 2: Check for Idempotency Rejection&quot;">​</a></h3><p>Search the logs for: <code>Idempotency rejection: MD5 [hash] already exists</code>.</p><ul><li><strong>Cause</strong>: The same payload was already processed.</li><li><strong>Solution</strong>: Check your main transaction table for an existing entry with that amount/date.</li></ul><h3 id="step-3-inspect-the-triage-queue" tabindex="-1">Step 3: Inspect the Triage Queue <a class="header-anchor" href="#step-3-inspect-the-triage-queue" aria-label="Permalink to &quot;Step 3: Inspect the Triage Queue&quot;">​</a></h3><ol><li>Navigate to <strong>Transactions → Triage</strong>.</li><li>Look for the transaction in the <strong>Unparsed Messages</strong> section.</li><li>If found here, the parser failed to extract the data with high confidence.</li><li><strong>Action</strong>: Manually parse the message and save it as a new <strong>Pattern</strong> to prevent future failure.</li></ol><h3 id="step-4-validate-regular-expression-coverage" tabindex="-1">Step 4: Validate Regular Expression Coverage <a class="header-anchor" href="#step-4-validate-regular-expression-coverage" aria-label="Permalink to &quot;Step 4: Validate Regular Expression Coverage&quot;">​</a></h3><ol><li>Go to <strong>Settings → Parser Rules</strong>.</li><li>Test your raw message against the listed regex patterns.</li><li>If no match is found, your bank&#39;s message format may have changed.</li><li><strong>Action</strong>: Use the <strong>Neural Training</strong> feature on mobile to update the pattern library.</li></ol><hr><h2 id="🏛️-separation-of-concerns-consumer-invisibility-vs-dedicated-operations-portal" tabindex="-1">🏛️ Separation of Concerns: Consumer Invisibility vs. Dedicated Operations Portal <a class="header-anchor" href="#🏛️-separation-of-concerns-consumer-invisibility-vs-dedicated-operations-portal" aria-label="Permalink to &quot;🏛️ Separation of Concerns: Consumer Invisibility vs. Dedicated Operations Portal&quot;">​</a></h2><p>A core architectural tenet of WealthFam is that <strong>a consumer end-user should never need to know what the parser is doing under the hood</strong>.</p><ol><li><p><strong>Consumer Experience (WealthFam Web &amp; Mobile)</strong>:</p><ul><li>Zero exposure to regex expressions, sandbox tools, engine latency, or DuckDB request logs.</li><li>Ingestion operates silently: SMS messages and email statement attachments arrive, parse in the background, and seamlessly populate the user&#39;s ledger and statement workspaces.</li><li>Any unparseable transaction surfaces only as a simple, human-friendly triage prompt asking for category or merchant confirmation.</li><li><strong>Ground-Truth Reconciliation</strong>: Reconciling statement lines automatically promotes matching items in <code>PendingTransaction</code> triage into approved ledger entries without duplicate key rejections or <code>NoneType</code> crashes.</li><li><strong>PostgreSQL JSONB Compatibility</strong>: Classification rules generated from statement descriptions use <code>cast(keywords, String).ilike()</code> for full cross-database compatibility.</li></ul></li><li><p><strong>Dedicated Operations Portal (Independent Admin Console)</strong>:</p><ul><li>Internal administrative tooling is decoupled into a dedicated developer/operations web app.</li><li>Houses the <strong>Parser Sandbox</strong>, <strong>Pattern CRUD Manager</strong>, <strong>DuckDB Request Logs</strong>, and <strong>Health Probes</strong>.</li><li>Ensures engineering and debugging capabilities remain powerful without cluttering or intimidating the consumer product experience.</li></ul></li></ol><hr><div align="center"> *Accuracy Above All · Zero Manual Entry · Precision Integrity* *Made with ❤️ by WGLabz* </div>',30))])}const I=d(u,[["render",p]]);export{S as __pageData,I as default};
